"""Review specification; no live data mutation. Evidence is factual, not gold labels."""
import json
from pathlib import Path
p = Path(__file__).parent
spec = {'evidence': {}, 'identities': [], 'decisions': [], 'names': [], 'followups': []}
def case(code, url, note, keys, roles, aff='unknown', status='pending', name=None, chain=None, action=None):
    spec['evidence'][code] = {'url': url, 'note': note + ' Evidence packet: data/validation/museum_jefferson_lincoln_2026-09-26; original source fields and coordinates retained.'}
    if roles:
        spec['identities'].append({'case':code,'keys':keys,'roles':roles,'groups':['unresolved_source' if r=='source_conflict' else code.lower()+'_former' if r=='former_site' else code.lower() for r in roles]})
    spec['decisions'].append({'key':keys[0],'case':code,'aff':aff,'status':status,'chain':chain,'category':'not_flagged'})
    if name:spec['names'].append({'key':keys[0],'case':code,'name':name})
    if action:spec['followups'].append({'key':keys[0],'case':code,'action':action})

